<?php
declare(strict_types=1);
namespace App\Services;
use App\Support\Database;
final class InvestmentService {
 public function __construct(private ?Database $db,private WalletService $wallets,private OfferingCalculator $calculator,private LicenseService $licenses,private NotificationService $notifications){}
 public function quote(array $user,array $country,int $offeringId,string $quantity):array{if(!$this->db)throw new \RuntimeException('Database unavailable.');$o=$this->db->one('SELECT o.*,c.id company_id,c.display_name,c.status company_status FROM investment_offerings o JOIN companies c ON c.id=o.company_id WHERE o.id=? AND o.country_id=?',[$offeringId,$country['id']]);if(!$o||!$o['is_active']||$o['company_status']!=='ACTIVE'||($o['available_from']&&strtotime($o['available_from'])>time())||($o['available_until']&&strtotime($o['available_until'])<time()))throw new \RuntimeException('Investment is unavailable.');if(!$this->licenses->canInvest($country))throw new \RuntimeException('Investment purchases are temporarily unavailable.');$quote=$this->calculator->calculate($o,$quantity,new \DateTimeImmutable('now'));return ['offering'=>$o,'quote'=>$quote];}
 public function purchase(array $user,array $country,int $offeringId,string $quantity,string $idempotency):array{if(!$this->db)throw new \RuntimeException('Database unavailable.');if(($user['account_status']??'')!=='ACTIVE')throw new \RuntimeException('Your account is not permitted to invest.');$position=$this->db->transaction(function(Database $db)use($user,$country,$offeringId,$quantity,$idempotency){$existing=$db->one('SELECT * FROM investment_positions WHERE JSON_UNQUOTE(JSON_EXTRACT(metadata,"$.idempotency"))=?',[$idempotency]);if($existing)return $existing;$data=$this->quote($user,$country,$offeringId,$quantity);$o=$db->lockForUpdate('SELECT o.*,c.id company_id,c.display_name,c.status company_status FROM investment_offerings o JOIN companies c ON c.id=o.company_id WHERE o.id=? AND o.country_id=?',[$offeringId,$country['id']]);if(!$o||!$o['is_active']||$o['company_status']!=='ACTIVE')throw new \RuntimeException('Investment is unavailable.');$quote=$this->calculator->calculate($o,$quantity,new \DateTimeImmutable('now'));$wallet=$this->wallets->walletFor($user,$country);if($wallet['currency_code']!==$o['currency_code'])throw new \RuntimeException('Wallet currency does not match offering.');if($o['maximum_purchase_quantity']!==null&&$this->decimalCompare($quantity,(string)$o['maximum_purchase_quantity'])>0)throw new \RuntimeException('Purchase exceeds the maximum quantity.');if($o['maximum_user_holding']!==null){$held=(string)($db->scalar('SELECT COALESCE(SUM(quantity),0) FROM investment_positions WHERE user_id=? AND investment_offering_id=? AND status IN ("ACTIVE","SALE_REQUESTED")',[$user['id'],$o['id']])??'0');if($this->decimalCompare($this->decimalAdd($held,$quantity),(string)$o['maximum_user_holding'])>0)throw new \RuntimeException('Purchase exceeds your maximum holding.');}if($o['total_available_shares']!==null){$sold=(string)($db->scalar('SELECT COALESCE(SUM(quantity),0) FROM investment_positions WHERE investment_offering_id=? AND status NOT IN ("CANCELLED")',[$o['id']])??'0');if($this->decimalCompare($this->decimalAdd($sold,$quantity),(string)$o['total_available_shares'])>0)throw new \RuntimeException('Investment inventory is unavailable.');}$id='INV-'.strtoupper(bin2hex(random_bytes(8)));$ledger=$this->wallets->move((int)$wallet['id'],'INVESTMENT_PURCHASE','DEBIT',$quote['investment']->minor,'Investment purchase','investment',$id,null);$db->execute('INSERT INTO investment_positions(public_id,user_id,wallet_id,company_id,investment_offering_id,country_id,currency_code,company_name_snapshot,quantity,share_price_minor_snapshot,principal_amount_minor,profit_type_snapshot,projected_profit_value_snapshot,fixed_profit_basis_snapshot,projected_profit_amount_minor,duration_value_snapshot,duration_unit_snapshot,purchased_at,maturity_date,purchase_ledger_transaction_id,metadata) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$user['id'],$wallet['id'],$o['company_id'],$o['id'],$country['id'],$o['currency_code'],$o['display_name'],$quantity,$o['share_price_minor'],$quote['investment']->minor,$o['profit_type'],$o['projected_profit_value'],$o['fixed_profit_basis'],$quote['projected_profit']->minor,$o['duration_value'],$o['duration_unit'],date('Y-m-d H:i:s'),$quote['maturity_date']->format('Y-m-d H:i:s'),$ledger['id'],json_encode(['idempotency'=>$idempotency,'legal_acknowledged_at'=>date(DATE_ATOM)])]);return $db->one('SELECT * FROM investment_positions WHERE id=?',[(int)$db->pdo()->lastInsertId()]);});$this->notifications->create((int)$user['id'],'investment_purchased','Investment purchased','Your investment position has been created.',['url'=>'/dashboard/investments/'.$position['public_id']]);return $position;}
 public function forUser(int $userId,array $filters=[]):array{if(!$this->db)return[];$where=['i.user_id=?'];$p=[$userId];if(($filters['status']??'')!==''){$where[]='i.status=?';$p[]=$filters['status'];}return $this->db->select('SELECT i.*,c.slug,c.display_name FROM investment_positions i LEFT JOIN companies c ON c.id=i.company_id WHERE '.implode(' AND ',$where).' ORDER BY i.purchased_at DESC',$p);}
 public function findForUser(int $userId,string $reference):?array{return $this->db?->one('SELECT i.*,c.display_name,c.ticker,c.stock_exchange FROM investment_positions i LEFT JOIN companies c ON c.id=i.company_id WHERE i.user_id=? AND i.public_id=?',[$userId,$reference]);}
 public function portfolio(int $userId):array{if(!$this->db)return [];return $this->db->one('SELECT COALESCE(SUM(CASE WHEN status IN("ACTIVE","SALE_REQUESTED") THEN principal_amount_minor ELSE 0 END),0) active_principal,COALESCE(SUM(CASE WHEN status IN("ACTIVE","SALE_REQUESTED") THEN projected_profit_amount_minor ELSE 0 END),0) projected_profit,COALESCE(SUM(CASE WHEN status="MATURED" THEN projected_profit_amount_minor ELSE 0 END),0) realized_profit,COALESCE(SUM(status="MATURED"),0) matured_count,COALESCE(SUM(status="SOLD"),0) sold_count,COALESCE(SUM(status IN("ACTIVE","SALE_REQUESTED")),0) active_count FROM investment_positions WHERE user_id=?',[$userId])??[];}
 public function requestSale(array $user,array $country,string $investmentRef):array{if(!$this->db)throw new \RuntimeException('Database unavailable.');$sale=$this->db->transaction(function(Database $db)use($user,$country,$investmentRef){$i=$db->lockForUpdate('SELECT i.*,o.selling_enabled,o.share_price_minor FROM investment_positions i JOIN investment_offerings o ON o.id=i.investment_offering_id WHERE i.public_id=? AND i.user_id=? AND i.country_id=?',[$investmentRef,$user['id'],$country['id']]);if(!$i||$i['status']!=='ACTIVE'||!$i['selling_enabled'])throw new \RuntimeException('This investment is not available for sale.');$exists=$db->one('SELECT id FROM sale_requests WHERE investment_id=? AND status IN ("PENDING","UNDER_REVIEW")',[$i['id']]);if($exists)throw new \RuntimeException('A sale request is already active.');$ref='SAL-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(6)));$db->execute('INSERT INTO sale_requests(public_id,reference,investment_id,user_id,country_id,requested_quantity,sale_price_minor_snapshot,sale_value_minor) VALUES (?,?,?,?,?,?,?,?)',[bin2hex(random_bytes(16)),$ref,$i['id'],$user['id'],$country['id'],$i['quantity'],$i['share_price_minor'],$this->saleValue((string)$i['quantity'],(int)$i['share_price_minor'])]);$id=(int)$db->pdo()->lastInsertId();$db->execute('UPDATE investment_positions SET status="SALE_REQUESTED",updated_at=NOW() WHERE id=?',[$i['id']]);return $db->one('SELECT * FROM sale_requests WHERE id=?',[$id]);});$this->notifications->create((int)$user['id'],'sale_requested','Sale request submitted','Your request is awaiting review.',['url'=>'/dashboard/investments/'.$investmentRef]);return $sale;}
 public function approveSale(int $saleId,int $adminId,?int $price=null):array{if(!$this->db)throw new \RuntimeException('Database unavailable.');$result=$this->db->transaction(function(Database $db)use($saleId,$adminId,$price){$sale=$db->lockForUpdate('SELECT * FROM sale_requests WHERE id=?',[$saleId]);if(!$sale)throw new \RuntimeException('Sale request not found.');if($sale['status']==='APPROVED'&&$sale['sale_ledger_transaction_id'])return ['idempotent'=>true,'user_id'=>$sale['user_id']];if(!in_array($sale['status'],['PENDING','UNDER_REVIEW'],true))throw new \RuntimeException('Sale request cannot be approved.');$investment=$db->lockForUpdate('SELECT i.*,o.share_price_minor FROM investment_positions i JOIN investment_offerings o ON o.id=i.investment_offering_id WHERE i.id=?',[$sale['investment_id']]);if(!$investment||$investment['status']!=='SALE_REQUESTED')throw new \RuntimeException('Investment is not sale eligible.');$finalPrice=$price??(int)$investment['share_price_minor'];if($finalPrice<=0)throw new \RuntimeException('Invalid sale price.');$value=$this->saleValue((string)$sale['requested_quantity'],$finalPrice);$ledger=$this->wallets->move((int)$investment['wallet_id'],'SHARE_SALE','CREDIT',$value,'Approved investment sale','sale',(string)$sale['id'],$adminId);$db->execute('UPDATE sale_requests SET status="APPROVED",sale_price_minor_snapshot=?,sale_value_minor=?,reviewed_at=NOW(),reviewed_by_user_id=?,sale_ledger_transaction_id=? WHERE id=?',[$finalPrice,$value,$adminId,$ledger['id'],$saleId]);$db->execute('UPDATE investment_positions SET status="SOLD",sold_at=NOW(),updated_at=NOW() WHERE id=?',[$investment['id']]);return $ledger+['user_id'=>$sale['user_id']];});$this->notifications->create((int)$result['user_id'],'sale_approved','Sale approved','Your sale proceeds have been credited.',['url'=>'/dashboard/investments']);return $result;}
 public function rejectSale(int $saleId,int $adminId,string $reason):void{if(trim($reason)==='')throw new \InvalidArgumentException('A rejection reason is required.');if(!$this->db)return;$this->db->transaction(function(Database $db)use($saleId,$adminId,$reason){$s=$db->lockForUpdate('SELECT * FROM sale_requests WHERE id=?',[$saleId]);if(!$s||!in_array($s['status'],['PENDING','UNDER_REVIEW'],true))throw new \RuntimeException('Sale request cannot be rejected.');$db->execute('UPDATE sale_requests SET status="REJECTED",rejection_reason=?,reviewed_at=NOW(),reviewed_by_user_id=? WHERE id=?',[$reason,$adminId,$saleId]);$db->execute('UPDATE investment_positions SET status="ACTIVE",updated_at=NOW() WHERE id=? AND status="SALE_REQUESTED"',[$s['investment_id']]);$this->notifications->create((int)$s['user_id'],'sale_rejected','Sale request rejected',$reason,['url'=>'/dashboard/investments']);});}
 public function matureDue(bool $dry=false,int $limit=100):array{if(!$this->db)return[];$due=$this->db->select('SELECT id FROM investment_positions WHERE status="ACTIVE" AND maturity_date<=NOW() ORDER BY maturity_date LIMIT '.max(1,min($limit,500)));$done=[];foreach($due as$r){if($dry){$done[]=$r['id'];continue;}$result=$this->db->transaction(function(Database $db)use($r){$i=$db->lockForUpdate('SELECT * FROM investment_positions WHERE id=?',[$r['id']]);if(!$i||$i['status']!=='ACTIVE'||strtotime($i['maturity_date'])>time())return null;$a=$this->wallets->move((int)$i['wallet_id'],'INVESTMENT_PRINCIPAL_RETURN','CREDIT',(int)$i['principal_amount_minor'],'Investment principal returned','investment-principal',(string)$i['id']);$b=$this->wallets->move((int)$i['wallet_id'],'INVESTMENT_PROFIT','CREDIT',(int)$i['projected_profit_amount_minor'],'Investment projected profit credited','investment-profit',(string)$i['id']);$db->execute('UPDATE investment_positions SET status="MATURED",matured_at=NOW(),maturity_principal_ledger_transaction_id=?,maturity_profit_ledger_transaction_id=? WHERE id=?',[$a['id'],$b['id'],$i['id']]);return $i;});if($result){$done[]=$result['id'];$this->notifications->create((int)$result['user_id'],'investment_matured','Investment matured','Principal and projected profit have been credited.',['url'=>'/dashboard/investments/'.$result['public_id']]);}}return $done;}
 private function saleValue(string $quantity,int $price):int{return intdiv($this->scaled($quantity)*$price,100000000);}
 private function scaled(string $value):int{$negative=str_starts_with($value,'-');$value=ltrim($value,'+-');[$whole,$fraction]=array_pad(explode('.',$value,2),2,'');$scaled=(int)$whole*100000000+(int)str_pad(substr($fraction,0,8),8,'0');return $negative?- $scaled:$scaled;}private function decimalCompare(string $a,string $b):int{return $this->scaled($a)<=>$this->scaled($b);}private function decimalAdd(string $a,string $b):string{$sum=$this->scaled($a)+$this->scaled($b);$whole=intdiv($sum,100000000);$fraction=str_pad((string)abs($sum%100000000),8,'0',STR_PAD_LEFT);return $whole.'.'.$fraction;}
}
